CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE membership_status AS ENUM ('draft','submitted','paymentConfirmed','pendingReview','active','rejected','expired');
CREATE TYPE donation_frequency AS ENUM ('oneOff','monthly');
CREATE TYPE donation_status AS ENUM ('pending','confirmed','failed','cancelled');
CREATE TABLE users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), email VARCHAR(255) NOT NULL UNIQUE, first_name VARCHAR(100) NOT NULL, last_name VARCHAR(100) NOT NULL, country VARCHAR(100) NOT NULL, password_hash TEXT NOT NULL, directory_visible BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), deleted_at TIMESTAMPTZ);
CREATE TABLE refresh_tokens (id UUID PRIMARY KEY, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash CHAR(64) NOT NULL UNIQUE, expires_at TIMESTAMPTZ NOT NULL, revoked_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE memberships (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), plan VARCHAR(40) NOT NULL, amount_cents INTEGER NOT NULL CHECK (amount_cents >= 0), djerba_connection TEXT, motivation TEXT, status membership_status NOT NULL DEFAULT 'draft', submitted_at TIMESTAMPTZ, paid_at TIMESTAMPTZ, expires_at DATE, rejection_reason TEXT, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE projects (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title VARCHAR(200) NOT NULL, category VARCHAR(60) NOT NULL, summary TEXT NOT NULL, body TEXT, location VARCHAR(200) NOT NULL DEFAULT 'Djerba', progress NUMERIC(5,4) NOT NULL DEFAULT 0 CHECK (progress BETWEEN 0 AND 1), target_cents INTEGER, raised_cents INTEGER NOT NULL DEFAULT 0, featured BOOLEAN NOT NULL DEFAULT FALSE, published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE news (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title VARCHAR(240) NOT NULL, excerpt TEXT NOT NULL, body TEXT, category VARCHAR(60), cover_image_url TEXT, published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE events (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), title VARCHAR(240) NOT NULL, summary TEXT, location VARCHAR(240), starts_at TIMESTAMPTZ, ends_at TIMESTAMPTZ, published BOOLEAN NOT NULL DEFAULT FALSE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE donations (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID REFERENCES users(id), project_id UUID REFERENCES projects(id), donor_email VARCHAR(255), anonymous BOOLEAN NOT NULL DEFAULT FALSE, amount_cents INTEGER NOT NULL CHECK (amount_cents > 0), frequency donation_frequency NOT NULL, status donation_status NOT NULL DEFAULT 'pending', helloasso_checkout_intent_id VARCHAR(128) UNIQUE, helloasso_order_id VARCHAR(128) UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE networking_profiles (user_id UUID PRIMARY KEY REFERENCES users(id), city VARCHAR(100), sector VARCHAR(120), skills TEXT[] NOT NULL DEFAULT '{}', visibility JSONB NOT NULL DEFAULT '{}'::jsonb, updated_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE networking_requests (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), requester_id UUID NOT NULL REFERENCES users(id), recipient_id UUID NOT NULL REFERENCES users(id), status VARCHAR(16) NOT NULL CHECK (status IN ('pending','accepted','declined')), created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(requester_id, recipient_id));
CREATE TABLE notifications (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), type VARCHAR(50) NOT NULL, title VARCHAR(240) NOT NULL, body TEXT, read_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE device_tokens (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), token VARCHAR(255) NOT NULL UNIQUE, platform VARCHAR(20) NOT NULL, preferences JSONB NOT NULL DEFAULT '{}'::jsonb, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE consents (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES users(id), purpose VARCHAR(64) NOT NULL, granted BOOLEAN NOT NULL, recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE helloasso_webhook_events (event_id VARCHAR(128) PRIMARY KEY, event_type VARCHAR(80) NOT NULL, payload JSONB NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT now(), processed_at TIMESTAMPTZ, processing_error TEXT);
CREATE INDEX memberships_user_idx ON memberships(user_id, status); CREATE INDEX donations_user_idx ON donations(user_id, created_at DESC); CREATE INDEX notifications_user_idx ON notifications(user_id, created_at DESC);
